# tandem repeats: look for repeated 6mers and periodicity
def tandems(s,minlen=8,maxp=200):
    out=[]
    n=len(s)
    for p in range(minlen,maxp):
        i=0
        while i+p<=n:
            j=i
            while j+2*p<=n and s[j:j+p]==s[j+p:j+2*p]: j+=p
            if j-i>=2*p: out.append((i+1,j,p)); 
            i+= (j-i if j>i else p)
    return out
