# inverted repeats / self complementarity
def max_selfcomp(s):
    best=(0,0,0)
    n=len(s)
    for i in range(n):
        for L in range(10, min(60,n-i)):
            k=s[i:i+L]
            if rc(k) in s[i+L:]:
                if L>best[0]: best=(L,i+1,i+L+1)
    return best
